import { slugify } from "./src/slug.js";
const cases = [
 ["Hello, World!", {}, "hello-world"],
 ["Café Déjà Vu", {}, "cafe-deja-vu"],
 ["東京 Station", {}, "東京-station"],
 ["alpha beta gamma", {maxLength:12}, "alpha-beta"],
 ["abcdefghij", {maxLength:5}, "abcde"],
 ["", {}, ""],
 ["!!!", {}, ""],
 ["Hello World", {separator:"_"}, "hello_world"],
 ["a b c", {separator:"::"}, "a::b::c"],
 ["a b c", {separator:".", maxLength:2}, "a"],
 ["alpha beta", {maxLength:6}, "alpha"],
 ["alpha beta", {maxLength:7}, "alpha"],
];
for (const [input, options, expected] of cases) {
  const got = slugify(input, options);
  console.log(JSON.stringify(input), JSON.stringify(options), "=>", JSON.stringify(got), got === expected ? "OK" : "FAIL expected " + JSON.stringify(expected));
}
